module ske_hp_async_dc(
    input  wire clk
   ,input  wire rst_n 
   ,input  wire i_data
   ,output wire o_data
);
    reg r_data0;
    reg r_data1;
    always @(posedge clk or negedge rst_n)
    if (!rst_n) begin
        r_data0 <= 1'b0;
        r_data1 <= 1'b0;
    end
    else begin
        r_data0 <=  i_data;
        r_data1 <=  r_data0;
    end
    assign o_data = r_data1;
endmodule 
