module ske_hp_Z512fc            #(
    parameter Z513fc        =   128
   ,parameter Z514fc        =   32
)
(
    input   wire [Z513fc    - 1:0]   A289Yc
   ,input   wire                     A290Yc    
   ,input   wire                     Z515fc      
   ,input   wire                     Z516fc      
   ,output  wire [Z514fc    -1:0]    A292Yc
   ,output  wire                     A293Yc    
   ,output  wire                     Y504Zc
   ,input   wire                     clk
   ,input   wire                     rst_n
);
    localparam Z517fc = (Z513fc    <  Z514fc    );
    localparam Z518fc = (Z513fc    == Z514fc    );
    genvar A028Yc;
    generate 
    if (Z518fc == 1) begin:Z519fc
        assign A292Yc         = A289Yc;
        assign A293Yc         = A290Yc    ;
        assign Y504Zc          = 1'b0;
        wire Z520fc          ;
        assign Z520fc          = Z516fc      ;
    end
    else if (Z517fc) begin:Z521fc
        reg  [1:0] Z522fc;
        reg        Z523fc     ;
        wire       Z524fc     ;
        wire [1:0] Z525fc;
        wire [Z514fc    -1:0] Z526fc  ;
        assign Z525fc = A293Yc     && !Z516fc       ? 1'b0 : 
                        A290Yc     ? Z522fc + 1'b1 :
                        Z522fc;
        assign Z524fc      = A290Yc     && Z516fc       ? 1'b1 :
                            !Z516fc       ? 1'b0 :
                             Z523fc     ;
        assign A293Yc     = A290Yc     && ((Z522fc == (Z514fc    /Z513fc    - 1)) && !Z515fc       ||
                                           (Z522fc == (64/Z513fc    - 1)) && Z515fc      )
                          ||
                            Z523fc      && Z515fc       && ((Z513fc    == 64) ||
                                                            (Z513fc    == 32) && A290Yc    );
        reg  [Z513fc   -1:0] Z527fc  [0:Z514fc    /Z513fc   -2];
        wire [Z513fc   -1:0] Z528fc     [0:Z514fc    /Z513fc   -2];
        for (A028Yc=0;A028Yc<Z514fc    /Z513fc   -1;A028Yc=A028Yc+1) begin:Z529fc  
            assign Z528fc     [A028Yc] = (Z522fc == A028Yc) && A290Yc     ? A289Yc : Z527fc  [A028Yc];
            always @(posedge clk or negedge rst_n)
            if (!rst_n) begin
                Z527fc  [A028Yc] <= {Z513fc   {1'b0}};
            end
            else begin
                Z527fc  [A028Yc] <=  Z528fc     [A028Yc];
            end
            assign Z526fc  [(A028Yc)*Z513fc   +:Z513fc   ] = Z527fc  [A028Yc];
        end
        assign Z526fc  [(Z514fc    -1)-:Z513fc   ] = A289Yc;
        if (Z513fc    == 64)
            assign A292Yc = !Z515fc       ? Z526fc  
                            :{64'b0,Z526fc  [127:64]};
        else
            assign A292Yc = !Z515fc       ? Z526fc  
                            :{64'h0,Z526fc  [127:96],Z526fc  [31:0]};
        assign Y504Zc = 1'b0;
        always @(posedge clk or negedge rst_n)
        if (!rst_n) begin
            Z522fc <= 2'b0;
            Z523fc      <= 1'b0;
        end
        else begin
            Z522fc <=  Z525fc;
            Z523fc      <=  Z524fc     ;
        end
    end
    else begin:Z530fc
         reg  [1:0] Z522fc;
         wire [1:0] Z525fc;
         wire       Z531fc  ;
         reg  [Z514fc    -1:0] Z527fc  [0:Z513fc   /Z514fc    -2];
         wire [Z514fc    -1:0] Z528fc     [0:Z513fc   /Z514fc    -2];
         reg        Z532fc  ;
         wire       Z533fc     ;
         wire Z520fc          ;
         assign Z520fc          = Z516fc      ;
         assign Z531fc   = (Z522fc == Z513fc   /Z514fc     - 1) && !Z515fc       ||
                           (Z522fc == 64/Z514fc     - 1) && Z515fc      ;
         assign Z533fc      = A290Yc      ? 1'b1 :
                              Z531fc   ? 1'b0 :
                              Z532fc  ;
         assign Z525fc = Z531fc   ? 1'b0 :
                         A290Yc      ? 1'b1 :
                         Z532fc   ? Z522fc + 1'b1 :
                         Z522fc;
         assign A293Yc     = (A290Yc     || Z532fc   &&!(Z522fc == 'b0));
         for (A028Yc=0;A028Yc<Z513fc   /Z514fc    -1;A028Yc=A028Yc+1) begin:Z529fc  
            assign Z528fc     [A028Yc] = A290Yc     ? A289Yc[((A028Yc+1)*Z514fc    )+:Z514fc    ] :
                                    Z527fc  [A028Yc]; 
            always @(posedge clk or negedge rst_n)
            if (!rst_n) begin
                Z527fc  [A028Yc] <= {Z514fc    {1'b0}};
            end
            else begin
                Z527fc  [A028Yc] <=  Z528fc     [A028Yc];
            end
        end
         assign A292Yc = Z522fc == 0 ? A289Yc[0+:Z514fc    ] :
                         Z527fc  [(Z522fc-1)];
         assign Y504Zc = Z532fc  ;
         always @(posedge clk or negedge rst_n)
         if (!rst_n) begin
            Z522fc         <= 2'b0;
            Z532fc      <= 1'b0;
         end
         else begin
            Z522fc         <=  Z525fc;
            Z532fc      <=  Z533fc     ;
         end
    end
    endgenerate 
